import { FC } from 'react';

import CloseOutlined from '@ant-design/icons/CloseOutlined';

import type { SelectProps } from 'antd';
import { Flex, Select } from 'antd';

import styles from './CustomSelect.module.scss';

interface ICustomSelectProps extends SelectProps {}

export const CustomSelect: FC<ICustomSelectProps> = ({ children, value, options, onChange, ...props }) => {
	return (
		<Flex vertical gap={8}>
			<Select {...props} value={value} options={options} onChange={onChange}>
				{children}
			</Select>
			<Flex gap={4} wrap>
				{options?.map(
					(item) =>
						(item.value === value || value?.includes(item.value)) && (
							<Flex align="center" gap={8} className={styles.label}>
								<span>{item.label}</span>
								<button
									className={styles.close}
									onClick={() =>
										onChange?.(typeof value === 'string' ? '' : value.filter((v: string) => v !== item.value))
									}>
									<CloseOutlined />
								</button>
							</Flex>
						),
				)}
			</Flex>
		</Flex>
	);
};
