import { FC, HTMLAttributes, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { useNavigate, useParams } from 'react-router-dom';

import { Button, Card, Flex, Form, notification, Select } from 'antd';
import { Formik } from 'formik';
import * as Yup from 'yup';

import { ChannelTypeEnum, Source, useSourcesRetrieveQuery, useSourcesUpdateMutation } from 'entities/Channel';
import { useMetaRetrieveQuery } from 'shared/api';
import { useBackButton, useNotFoundError } from 'shared/hooks';
import { EMainRoutes } from 'shared/typings';
import {
	BottomPanel,
	ButtonStyleLink,
	Content,
	CustomSelect,
	InputClearIcon,
	OverlayLoader,
	Page,
	PageTitle,
} from 'shared/ui';

import styles from './EditChannel.module.scss';

interface IEditChannelProps extends HTMLAttributes<HTMLDivElement> {}

export const EditChannel: FC<IEditChannelProps> = () => {
	const { t } = useTranslation();
	const params = useParams<{ id: string }>();
	const { data: channel, isFetching, error } = useSourcesRetrieveQuery(params?.id || '');

	const validationSchema = Yup.object({
		channel_type: Yup.string().required(t('Это поле обязательно для заполнения')),
		countries: Yup.array().min(1, t('Это поле обязательно для заполнения')),
		categories: Yup.array().min(1, t('Это поле обязательно для заполнения')),
		languages: Yup.array().min(1, t('Это поле обязательно для заполнения')),
	});

	const [updateSource, { isLoading: isUpdateLoading, isSuccess: isUpdateSuccess }] = useSourcesUpdateMutation();

	const { data: metaData, isLoading: isMetaLoading } = useMetaRetrieveQuery();

	useNotFoundError(error);
	useBackButton(`/${EMainRoutes.CHANNEL}/${params?.id}`);

	const navigate = useNavigate();

	useEffect(() => {
		if (!isUpdateSuccess) return;

		navigate(`/${EMainRoutes.CHANNEL}/${params?.id}`);

		notification.success({
			message: t('Информация о канале обновлена'),
			placement: 'bottom',
			showProgress: true,
			pauseOnHover: true,
		});
	}, [isUpdateSuccess]); // eslint-disable-line

	if (!channel) return null;

	return (
		<Page className={styles.page}>
			<PageTitle subtitle={t('Уточните информацию о вашем канале, если бот неверно считал ваши данные')}>
				{t('Редактирование информации о канале')}
			</PageTitle>

			<Content className={styles.content} bordered={false}>
				{isFetching && <OverlayLoader />}

				<Formik
					initialValues={channel}
					enableReinitialize
					validationSchema={validationSchema}
					onSubmit={(values) => {
						updateSource({ uuid: params?.id || '', source: values as Source });
					}}>
					{({ values, errors, touched, handleBlur, handleSubmit, setFieldValue }) => {
						return (
							<form onSubmit={handleSubmit}>
								<Flex vertical gap={16}>
									<Card variant="borderless">
										<Form.Item
											layout="vertical"
											label={`${t('Тип канала')}`}
											validateStatus={errors.channel_type && touched.channel_type ? 'error' : ''}
											help={errors.channel_type && touched.channel_type && errors.channel_type}>
											<Select
												size="large"
												options={[
													{ value: ChannelTypeEnum.Content, label: 'Контент' },
													{ value: ChannelTypeEnum.Promo, label: 'Промо' },
												]}
												onChange={(e) => setFieldValue('channel_type', e)}
												onBlur={handleBlur}
												value={values.channel_type}
												showSearch
												optionFilterProp="label"
												placeholder={t('Выберите тип канала')}
												allowClear={{ clearIcon: <InputClearIcon /> }}
												disabled={isUpdateLoading || isMetaLoading}
											/>
										</Form.Item>
									</Card>

									<Card variant="borderless">
										<Form.Item
											layout="vertical"
											label={`${t('Категории')}`}
											validateStatus={errors.categories && touched.categories ? 'error' : ''}
											help={errors.categories && touched.categories && errors.categories}>
											<CustomSelect
												size="large"
												options={metaData?.sourceCategoryOptions}
												onChange={(e) => setFieldValue('categories', e)}
												onBlur={handleBlur}
												value={values.categories}
												mode="multiple"
												maxTagCount="responsive"
												showSearch
												optionFilterProp="label"
												placeholder={t('Выберите категории')}
												allowClear={{ clearIcon: <InputClearIcon /> }}
												disabled={isUpdateLoading || isMetaLoading}
											/>
										</Form.Item>
									</Card>

									<Card variant="borderless">
										<Form.Item
											layout="vertical"
											label={`${t('Язык')}`}
											validateStatus={errors.languages && touched.languages ? 'error' : ''}
											help={errors.languages && touched.languages && errors.languages}>
											<CustomSelect
												size="large"
												options={metaData?.sourceLanguagesOptions}
												onChange={(e) => setFieldValue('languages', e)}
												onBlur={handleBlur}
												value={values.languages}
												mode="multiple"
												maxTagCount="responsive"
												showSearch
												optionFilterProp="label"
												placeholder={t('Выберите язык')}
												allowClear={{ clearIcon: <InputClearIcon /> }}
												disabled={isUpdateLoading || isMetaLoading}
											/>
										</Form.Item>
									</Card>

									<Card variant="borderless">
										<Form.Item
											layout="vertical"
											label={`${t('ГЕО')}`}
											validateStatus={errors.countries && touched.countries ? 'error' : ''}
											help={errors.countries && touched.countries && errors.countries}>
											<CustomSelect
												size="large"
												options={metaData?.countryOptions}
												onChange={(e) => setFieldValue('countries', e)}
												onBlur={handleBlur}
												value={values.countries}
												mode="multiple"
												maxTagCount="responsive"
												showSearch
												optionFilterProp="label"
												placeholder={t('Выберите ГЕО')}
												allowClear={{ clearIcon: <InputClearIcon /> }}
												disabled={isUpdateLoading || isMetaLoading}
											/>
										</Form.Item>
									</Card>

									<BottomPanel>
										<Flex justify="space-between" align="center" gap={8} className={styles.bottomPanel}>
											<ButtonStyleLink size="large" to={`/${EMainRoutes.CHANNEL}/${params?.id}`}>
												{t('Отменить')}
											</ButtonStyleLink>
											<Button
												size="large"
												type="primary"
												htmlType="submit"
												loading={isUpdateLoading}
												disabled={isUpdateLoading || !!Object.keys(errors).length}>
												{t('Сохранить')}
											</Button>
										</Flex>
									</BottomPanel>
								</Flex>
							</form>
						);
					}}
				</Formik>
			</Content>
		</Page>
	);
};

export default EditChannel;
